# the Stacks widget's part of fill (same sets, same this.last keys): one model, the changed .Text / .Value / .Visible only; true = the
# shape re-send (only a class change: "T|<class>", or hidden <-> shown). The box is fixed: no width check.
FXM(hudc, """
public boolean fillStacks(@UCB@ b, long now) {
  Object sh = this.shape.get("Stacks");
  if (sh == null) return false;
  @PR@ pr = getPlayerRef();
  @PKG@.WLayout ml = (@PKG@.WLayout) @PKG@.LayoutStore.get(this.uuid).get("Stacks");
  String[] mm = @PKG@.Widgets.modelL("Stacks", pr, ml);
  this.stkLast = mm;
  if (!sh.equals(mm[0])) return true;
  Object mg = this.built.get("Stacks");
  if (mg == null) return false;
  int gn = ((Integer) mg).intValue();
  String[] pairs = @PKG@.Widgets.linePairs("Stacks", mm);
  for (int k = 0; k + 1 < pairs.length; k += 2) {
    String key = "Stacks:" + pairs[k];
    if (!pairs[k + 1].equals(this.last.get(key))) { this.last.put(key, pairs[k + 1]); @PKG@.Widgets.setText(b, "#SkyyWStacks" + pairs[k], gn, pairs[k + 1]); }
  }
  String[] bps = @PKG@.Widgets.barPairs("Stacks", mm);
  for (int q = 0; q + 1 < bps.length; q += 2) {
    String bk = "Stacks:" + bps[q];
    if (!bps[q + 1].equals(this.last.get(bk))) {
      this.last.put(bk, bps[q + 1]);
      float fv = 0.0f;
      try { fv = Float.parseFloat(bps[q + 1]); } catch (Throwable x) { fv = 0.0f; }
      b.set("#SkyyWStacks" + bps[q] + ".Value", fv);
    }
  }
  String[] vps = @PKG@.Widgets.visPairs("Stacks", mm);
  for (int q = 0; q + 1 < vps.length; q += 2) {
    String vk = "Stacks:" + vps[q];
    if (!vps[q + 1].equals(this.last.get(vk))) { this.last.put(vk, vps[q + 1]); b.set("#SkyyWStacks" + vps[q] + ".Visible", "1".equals(vps[q + 1])); }
  }
  return false;
}""")
# a slot colour the markup does not have yet (a row first seen after the build): ONE re-send once the widget has been quiet (no Stacks set)
# for 10 s, at most once a minute - never while stacks are changing
FXM(hudc, """
public boolean stkRecolor(long now) {
  if (this.built.get("Stacks") == null || this.stkLast == null) return false;
  String[] bm = (String[]) this.models.get("Stacks");
  if (bm == null || @PKG@.Widgets.stkSig(bm).equals(@PKG@.Widgets.stkSig(this.stkLast))) return false;
  long q = this.stkAt > this.lastRe ? this.stkAt : this.lastRe;
  return now - q >= 10000L && now - this.stkRc >= 60000L;
}""")
FXM(hudc, """
public synchronized void stacksStep(long now) {
  try {
    @UCB@ b = new @UCB@();
    boolean re = fillStacks(b, now);
    if (re) { if (now - this.lastRe >= 1500L) { this.lastRe = now; show(); } return; }
    if (b.getCommands().length > 0) { this.stkAt = now; update(false, b); return; }
    if (stkRecolor(now)) { this.stkRc = now; this.lastRe = now; show(); }
  } catch (Throwable t) { }
}""")
